SELECT o.*
FROM orders o
WHERE o.merchant_id = #{merchantId}

    AND o.order_status = #{orderStatus}


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND o.receiver_phone LIKE CONCAT('%', #{phone}, '%')


    AND o.create_time >= #{startTime}


    AND o.create_time <= #{endTime}

ORDER BY o.create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM orders o
WHERE o.merchant_id = #{merchantId}

    AND o.order_status = #{orderStatus}


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND o.receiver_phone LIKE CONCAT('%', #{phone}, '%')


    AND o.create_time >= #{startTime}


    AND o.create_time <= #{endTime}

SELECT o.*
FROM orders o
WHERE o.order_no = #{orderNo}
  AND o.merchant_id = #{merchantId}

SELECT o.id, o.order_no, u.nickname as user_name, o.total_amount, o.order_status, o.create_time
FROM orders o
LEFT JOIN users u ON o.user_id = u.id
WHERE o.merchant_id = #{merchantId}
ORDER BY o.create_time DESC
LIMIT #{limit}

SELECT o.*
FROM orders o
LEFT JOIN admin a ON o.merchant_id = a.id
WHERE 1=1

    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND a.username LIKE CONCAT('%', #{merchantName}, '%')


    AND o.order_status = #{orderStatus}


    AND o.receiver_phone LIKE CONCAT('%', #{userPhone}, '%')


    AND o.create_time >= #{startTime}


    AND o.create_time <= #{endTime}

ORDER BY o.create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM orders o
LEFT JOIN admin a ON o.merchant_id = a.id
WHERE 1=1

    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND a.username LIKE CONCAT('%', #{merchantName}, '%')


    AND o.order_status = #{orderStatus}


    AND o.receiver_phone LIKE CONCAT('%', #{userPhone}, '%')


    AND o.create_time >= #{startTime}


    AND o.create_time <= #{endTime}

SELECT o.*
FROM orders o
WHERE o.order_no = #{orderNo}

